window.FILM_WORK_PROMPTS={"work_id":"src-9fe59975ff5169c8","records":[{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-bb935a4642554caa","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/0520 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"画面主体为连绵起伏的沙漠沙丘，占据画面下半部分，沙面布满细密波纹。上方为大面积淡蓝色天空，无云无物，整体呈现空旷、静谧的荒漠环境。","analysis":"构图上，沙丘脊线横贯画面中部，将画面分割为上下两部分，天空约占40%。无可见人物或动物，仅见沙丘大轮廓。视角接近平视，光线柔和均匀，无明显强光源方向。沙面呈黄褐色，受光面与背光面形成柔和明暗过渡，天空为均匀的淡蓝至灰白渐变，色彩层次简单。","prompt":"低分辨率画面，展现一片广阔沙漠景观。画面下半部为连绵起伏的沙丘，沙面覆盖细密的风蚀波纹纹理，呈黄褐色调，沙丘脊线柔和起伏，横贯画面中部。沙丘受光面明亮，背光面略暗，明暗过渡自然。画面上半部为大面积淡蓝色天空，颜色由地平线附近的灰白渐变至顶部的淡蓝，无云无物。整体光线柔和均匀，无强烈阴影，无可见人物、建筑或植被，呈现空旷静谧的荒漠氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:44:55-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/0520 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-13983455a4484475","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-87620daeaa4aa642","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/1620 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"画面主体为广阔平坦的灰白色地面，延伸至远方地平线。地平线正中站立着一个极小的黑色人影，上方是大面积纯净的蓝色天空。","analysis":"构图呈现极简风格，地平线横贯画面中部，将画面分割为上下两部分。人物位于画面正中央的地平线上，因距离极远仅呈现为微小的黑色直立剪影，无法辨识具体肢体细节或衣着。环境占比极大，地面占据画面下半部，天空占据上半部。光线均匀明亮，无明显阴影，色彩由地面的灰白与天空的淡蓝构成，对比清晰。","prompt":"这是一张低分辨率的极简风格画面，展现极度空旷的自然环境。画面被一条笔直的地平线水平分割，上方是纯净无云的淡蓝色天空，下方是广阔平坦的灰白色地面，地面带有细微的颗粒质感。在画面正中央的地平线上，站立着一个极小的黑色人影，人物呈直立姿态，因距离遥远仅可见模糊的深色轮廓，与周围明亮的浅色环境形成强烈对比。整体色调清冷，光线均匀，无明显的阴影投射，营造出一种孤独、静止且空旷的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:02-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/1620 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-48a95c68ae477414","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-8ad1d65adc6be959","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/2720 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"一名身穿长袍的男孩赤脚站在沙地上，右手握着一根细长的杆子，杆头挂着白色物体。背景是土黄色的平顶房屋群，远处地平线平坦，天空呈淡蓝色。","analysis":"人物位于画面中央，全身可见，头部至赤脚清晰。人物高度约占画面垂直方向的三分之二，与背景房屋形成近大远小的比例。镜头视角接近平视，光线从上方照射，人物面部和长袍正面受光，脚下沙地有阴影。色彩以沙土黄、长袍的灰白条纹和天空的淡蓝为主，整体色调温暖且对比度适中。","prompt":"低分辨率画面，一名短发男孩赤脚站在起伏的沙地上，身穿灰白竖条纹长袍，右手握着一根细长的杆子，杆头挂着白色物体。背景是连绵的土黄色平顶房屋，远处地平线平坦，天空呈淡蓝色。人物位于画面中央，全身可见，头部至赤脚清晰，人物高度约占画面垂直方向的三分之二。镜头视角接近平视，光线从上方照射，人物面部和长袍正面受光，脚下沙地有阴影。色彩以沙土黄、长袍的灰白条纹和天空的淡蓝为主，整体色调温暖且对比度适中。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:09-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/2720 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9211e2f164fe953a","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-f39ef46bfb18b525","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/3820 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"两名男子站立在土黄色的采石场或废墟中，左侧男子戴帽赤脚，右侧男子手持长柄工具，背景是堆积的石块和土墙。","analysis":"画面采用平视视角，两名人物全身可见，占据画面中下部。左侧人物身形略大，位于前景；右侧人物稍远，身形略小。环境由大面积的土黄色石块和墙壁构成，占据画面上半部及右侧。光线柔和，整体色调偏暖黄，阴影较淡，呈现出干燥、尘土飞扬的质感。","prompt":"低分辨率的土黄色调画面，展示了一个采石场或废墟环境。前景左侧站立一名男子，头戴宽檐帽，身穿浅色长袖衬衫和深色及膝短裤，赤脚站在碎石地面上。中景右侧站立另一名男子，身穿浅色长袍，手持一根长柄工具。背景上方堆积着大量不规则的浅色石块，右侧是一面粗糙的土黄色墙壁，墙上有一个拱形凹陷。整体光线均匀，色彩以米黄、土褐为主，画面充满颗粒感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:15-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/3820 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2ddbb95bf0e16f9a","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-3015d4085f46f738","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/4920 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"画面主体为广阔平坦的土黄色地面，远处地平线上伫立着几根细长的垂直杆状物，中间有一个极小的深色人影站立，背景是灰白天空与模糊的横向纹理带。","analysis":"构图呈现明显的水平分层，前景占据画面下半部约40%为平坦土黄色地面，中景为一条横向延伸的灰白色模糊带，远景为大面积灰蓝色天空。画面中央偏右有一个极小的深色直立人影，全身轮廓可见但细节模糊，人物高度仅占画面极小比例。几根细长的垂直杆状物分布在地平线附近，高度不一。整体光线均匀平淡，无明显阴影，色彩以土黄、灰白、灰蓝为主，对比度低，画面清晰度较低。","prompt":"低分辨率画面，前景为大面积平坦的土黄色地面，占据画面下半部分，地表纹理模糊呈颗粒感。中景处有一条横向延伸的灰白色模糊带，地平线附近竖立着数根细长的深色垂直杆状物，间距不等。画面中央偏右位置有一个极小的深色直立人影，全身轮廓可辨但无细节，人物高度极小。背景为大面积灰蓝色天空，色调均匀平淡。整体光线柔和无强烈阴影，色彩层次为土黄、灰白、灰蓝三色横向分布，画面清晰度低，颗粒感明显。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:45:23-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/4920 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-4a30ffd8e05a8d27","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-81007f23550f1186","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/0620 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"画面主体为广袤的沙漠地貌，前景散布着起伏的沙丘，中景为平坦的灰褐色戈壁滩，远景是连绵的低矮山脉，天空占据画面上部约三分之一。","analysis":"构图采用横向分层，前景沙丘、中景平地与远景山脉形成清晰的纵深空间。视角为平视略俯，光线均匀柔和，无强烈投影。色彩以土黄、灰褐与淡蓝为主，前景沙丘受光面呈浅黄，背光面形成深褐色阴影，整体色调干燥且层次分明。","prompt":"低分辨率的沙漠全景画面，前景分布着数个起伏的沙丘，沙脊线清晰，受光面呈浅土黄色，背光面投下深褐色阴影。中景是大片平坦开阔的灰褐色戈壁地面，延伸至远方。背景为连绵起伏的低矮山脉，轮廓在空气中略显朦胧。天空占据画面上部约三分之一，呈均匀的淡蓝色，无云。整体光线柔和均匀，色彩以大地色系为主，呈现出干燥、空旷的视觉质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:15:32+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/0620 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-126ca0721f6bd1e4","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-f6b787890b545b27","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/1720 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"画面主体为荒凉的火山地貌，前景是布满碎石与土块的坡地，中景可见一座带有黑色火山口的锥形山丘，远景是连绵起伏的暗色山脉，上方占据约一半画面的纯净蓝天。","analysis":"构图采用横向展开，地平线位于画面中下部，将画面分割为地面与天空两部分。前景岩石呈现粗糙的土黄色与褐色，受光面明亮，背光面有清晰阴影。中景火山口内部呈现深黑色，与周围褐色山体形成对比。远景山脉因大气透视呈现淡蓝灰色，轮廓柔和。整体光线强烈，色彩以大地色系与天蓝色为主，无可见人物或动物。","prompt":"这是一张低分辨率的荒凉地貌静帧。前景是粗糙的碎石坡地，散布着不规则的褐色与土黄色岩石块，岩石表面有明显的明暗光影。中景是一座巨大的褐色火山锥，顶部有一个清晰的黑色火山口凹陷，山体表面平滑。远景是层叠的暗色山脉，轮廓在大气中逐渐模糊，呈现淡蓝灰色调。天空占据画面上半部分，呈现纯净的深蓝色，无云。整体光线强烈，阴影清晰，色彩对比鲜明，呈现出干旱、空旷的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:15:38+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/1720 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-b31c6ea1cd77e7fd","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-471008bd8ed0b3c5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/2820 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"荒漠中，一名戴帽穿长袍的人物站立在左侧土路边缘，右侧是成片的土坯房屋，地面为沙土，天空灰白，整体环境空旷。","analysis":"人物位于画面左侧三分之一处，全身可见，呈站立姿态，身形在广阔环境中显得较小。右侧中景分布着低矮的土黄色建筑群，屋顶呈圆拱状。画面采用平视角度，光线均匀柔和，无明显阴影，色彩以沙土黄和灰白为主，层次平淡，呈现出干燥、静谧的视觉感受。","prompt":"低分辨率画面，展现一片干旱的荒漠村落。左侧前景，一名戴浅色圆帽、身披米白色长袍的人物站立在深灰色土路边缘，全身可见，身形在环境中显得渺小。右侧中景是连绵的土坯房屋，墙体呈沙黄色，屋顶为圆拱形，建筑低矮且密集。地面覆盖着浅黄色的沙土，质感粗糙。天空占据画面上半部分，呈灰白色，无云。整体光线均匀，无强烈阴影，色调以土黄、米白和灰白为主，画面氛围干燥、空旷且静谧。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:15:45+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/2820 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-15a4193df74ccdef","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-a57946e504d17b83","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/3920 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"荒漠土坡上，一名站立人物与两名蹲坐人物位于一处破败的木质棚屋前，右侧有强烈逆光，前景为粗糙的碎石地面。","analysis":"画面采用平视略俯角度，主体为占据中景的破败棚屋结构，左侧站立人物全身可见，身形瘦长，右侧棚屋处有两名蹲坐人物，仅见上半身轮廓。右侧棚屋开口处有极强白色高光溢出，形成逆光效果，导致棚屋内部及右侧人物处于剪影状态。前景地面占据画面下方约三分之一，布满碎石与土块，色调呈暖黄与灰白，整体画质颗粒感强，对比度极高。","prompt":"低分辨率、高颗粒感的荒漠场景静帧。画面主体为一处破败的木质棚屋结构，位于中景偏右，棚屋右侧开口处有强烈的白色逆光溢出，形成刺眼的高光。棚屋左侧站立一名身穿浅色长袍的人物，全身可见，身形瘦长。棚屋下方及右侧有两名蹲坐的人物，因逆光呈现深色剪影，仅可见上半身轮廓。前景为大面积的粗糙碎石土坡，占据画面下方三分之一，色调为暖黄与灰白，地面纹理粗糙不平。天空呈淡白色，整体光线强烈，明暗对比极大，画面带有明显的胶片噪点与模糊感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:15:52+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/3920 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-7e749bdf09a832ee","origin":"visual"},{"work_id":"src-9fe59975ff5169c8","frame_id":"FG-f09ad58fb60c8307","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/5020 (1).jpg","source_page":"https://film-grab.com/2016/05/04/fata-morgana/","scene":"室内舞台场景，一名男子坐在鼓组前，一名女子坐在钢琴前，上方悬挂彩色花环，墙上挂着吉他，前景有绳索围栏。","analysis":"画面采用平视视角，构图对称。左侧男子全身可见，坐于鼓后；右侧女子全身可见，坐于钢琴前。两人均位于画面中景，大小比例适中。上方悬挂的彩色花环呈弧形横跨画面，墙上两把吉他对称分布。光线从上方投射，人物面部和衣物受光，背景墙面较亮，前景围栏处于阴影中。色彩以暖色调为主，花环的鲜艳色彩与素色墙面形成对比。","prompt":"室内舞台场景，低分辨率画面。左侧一名男子坐在鼓组前，身穿浅色衬衫，戴墨镜，全身可见。右侧一名女子坐在黑色钢琴前，身穿深色花纹上衣，全身可见。两人之间上方悬挂着一条彩色花环，呈弧形横跨画面，花环下方有垂坠装饰。背景白色墙面上对称挂着两把吉他。前景有一排绳索围栏，将观众与舞台隔开。光线从上方投射，人物和乐器受光，背景墙面明亮，前景围栏处于阴影中。整体色调偏暖，花环的鲜艳色彩与素色墙面形成对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:15:59+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/5020 (1).jpg","observed_dimensions":[500,404],"source_thumbnail_dimensions":[500,404],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-0f00b2e5612dc5b2","origin":"visual"}]};